func (o *redhatBase) needsRestarting() error {
	initName, err := o.detectInitSystem()
	if err != nil {
		o.log.Warn(err)
		// continue scanning
	}

	cmd := "LANGUAGE=en_US.UTF-8 needs-restarting"
	r := o.exec(cmd, sudo)
	if !r.isSuccess() {
		return xerrors.Errorf("Failed to SSH: %w", r)
	}
	procs := o.parseNeedsRestarting(r.Stdout)
	for _, proc := range procs {
		fields := strings.Fields(strings.ReplaceAll(proc.Path, "\x00", " "))
		if len(fields) == 0 {
			continue
		}
		pkgNames, err := o.getOwnerPkgs(fields[:1])
		if err != nil {
			o.log.Warnf("Failed to detect a package name of need restarting process from the command path: %s, %s",
				proc.Path, err)
			continue
		}
		if len(pkgNames) == 0 {
			continue
		}
		if initName == systemd {
			name, err := o.detectServiceName(proc.PID)
			if err != nil {
				o.log.Warn(err)
				// continue scanning
			}
			proc.ServiceName = name
			proc.InitSystem = systemd
		}
		for _, pkgName := range pkgNames {
			pack := o.Packages[pkgName]
			pack.NeedRestartProcs = append(pack.NeedRestartProcs, proc)
			o.Packages[pkgName] = pack
		}
	}
	return nil
}

func (o *redhatBase) parseNeedsRestarting(stdout string) (procs []models.NeedRestartProcess) {
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := scanner.Text()
		line = strings.Replace(line, "\x00", " ", -1) // for CentOS6.9
		ss := strings.Split(line, " : ")
		if len(ss) < 2 {
			continue
		}
		// https://unix.stackexchange.com/a/419375
		if ss[0] == "1" {
			continue
		}

		path := ss[1]
		if !strings.HasPrefix(path, "/") {
			path = strings.Fields(path)[0]
			// [ec2-user@ip-172-31-11-139 ~]$ sudo needs-restarting
			// 2024 : auditd
			// [ec2-user@ip-172-31-11-139 ~]$ type -p auditd
			// /sbin/auditd
			cmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 which %s", path)
			r := o.exec(cmd, sudo)
			if !r.isSuccess() {
				o.log.Debugf("Failed to exec which %s: %s", path, r)
				continue
			}
			path = strings.TrimSpace(r.Stdout)
		}

		procs = append(procs, models.NeedRestartProcess{
			PID:     ss[0],
			Path:    path,
			HasInit: true,
		})
	}
	return
}

func (o *redhatBase) getOwnerPkgs(paths []string) ([]string, error) {
	if len(paths) == 0 {
		return nil, nil
	}

	quotedPaths := make([]string, len(paths))
	for i, path := range paths {
		quotedPaths[i] = "'" + strings.ReplaceAll(path, "'", "'\\''") + "'"
	}
	cmd := o.rpmQf() + strings.Join(quotedPaths, " ")
	r := o.exec(util.PrependProxyEnv(cmd), noSudo)
	// rpm exit code means `the number` of errors.
	// https://listman.redhat.com/archives/rpm-list/2005-July/msg00071.html
	// If we treat non-zero exit codes of `rpm` as errors,
	// we will be missing a partial package list we can get.
	if (r.Error != nil || r.ExitStatus != 0) && strings.TrimSpace(r.Stdout+r.Stderr) == "" {
		return nil, xerrors.Errorf("Failed to rpm -qf: %s", r)
	}
	return o.parseRPMQfOutput(r.Stdout + "\n" + r.Stderr)
}

func (o *redhatBase) parseRPMQfOutput(stdout string) ([]string, error) {
	var ownerPkgs []string
	seen := make(map[string]struct{})
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		ignored := false
		for _, suffix := range []string{
			"Permission denied",
			"is not owned by any package",
			"No such file or directory",
		} {
			if strings.HasSuffix(line, suffix) {
				ignored = true
				break
			}
		}
		if ignored {
			continue
		}

		fields := strings.Fields(line)
		if len(fields) != 5 {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
		}
		if fields[1] != "(none)" {
			if _, err := strconv.ParseUint(fields[1], 10, 64); err != nil {
				return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
			}
		}
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s: %w", line, err)
		}
		installed, ok := o.Packages[pack.Name]
		if !ok || installed.Version != pack.Version || installed.Release != pack.Release ||
			(installed.Arch != "" && installed.Arch != pack.Arch) {
			o.log.Debugf("Failed to match rpm -qf package to installed package: %+v", pack)
			continue
		}

